/* Release 131: names use all remaining space; only the secondary group is capped.
   Keep each view's typography and controls: differing structures need not truncate
   at an artificially identical width or character count. */
body .quick-asset .quick-asset-name-row{padding-inline:0;gap:2px}
body .quick-asset-name-row small{flex:0 1 auto;max-width:28%}
body :is(.asset-name-row,.quick-asset-name-row) b{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
